const CAPITAL_COLORS = {Citadelle:'#d7c177',Sylve:'#77b96b',Forteresse:'#a59a8f',Hameau:'#d8a85c',Nécropole:'#9c7ad6',Abîme:'#ba5f8b',Volcan:'#d35f45',Lagune:'#48a3bf',Désert:'#d7aa4d',Tour:'#6da7d9',Cénote:'#4cc3ca',Bastion:'#c27648',Tertre:'#9b8055',Empyrée:'#8fc7ff',Bosquet:'#73b96f'};
const QUOTES = [
  '« Là où son ombre tombe, les anciens pactes se réveillent. »',
  '« Aucun mage ne possède vraiment une créature : il négocie avec sa légende. »',
  '« Sa colère a le goût du métal, de la pluie et des vieux serments. »',
  '« Dans chaque carte dort un royaume, dans chaque royaume une menace. »',
  '« Le bestiaire n’est pas un livre : c’est une frontière. »',
  '« Qui prononce son nom achète une victoire et une dette. »'
];
const state = {
  gold: 80, mana: 6, maxMana: 6, day: 1, search: '', activeCapital: 'Toutes',
  collection: [], deckIds: [], deck: [], hand: [], board: [], enemyBoard: [], graveyard: [], enemyHp: 120, playerHp: 120, selectedAttackerUid: null, pendingSlot: 'front', pendingPos: 0, lastHit: '', lastGuardUid: '', lastGuardTargetUid: '',
  structures: {tower:20, village:20, wall:20}, enemyStructures: {tower:20, village:20, wall:20},
  log: [], location: 'Camp du Mage', mode: 'world', boosterOpened: false, lastBooster: []
};
const $ = (sel, root=document)=>root.querySelector(sel);
const byId = id => document.getElementById(id);
const rnd = arr => arr[Math.floor(Math.random()*arr.length)];
const shuffle = arr => arr.map(v=>[Math.random(),v]).sort((a,b)=>a[0]-b[0]).map(x=>x[1]);
function tierFor(c){ return Math.max(1, Math.min(8, c.cost || Math.ceil(c.power/12) || 1)); }
function stackCountFor(c){ const t=tierFor(c); return t*2 + ((c.id + c.power + c.popularity) % (t+1)); }
function deployedUnitsFor(c){ return Math.max(1, Math.round(30 / Math.max(1, stackCountFor(c)))); }
const clone = c => { const count=deployedUnitsFor(c); return {...c, uid: crypto.randomUUID?.() || Math.random().toString(36).slice(2), unitHp:c.health, maxHp:c.health*count, hp:c.health*count, count, exhausted:false}; };
function liveCount(c){ return Math.max(0, Math.ceil((c.hp ?? c.health) / (c.unitHp || c.health || 1))); }
function liveHp(c){ return c.hp ?? c.health; }
function displayHp(c){ return c.unitHp || c.health; }
function strikePower(c){ return Math.max(1, c.attack); }
function applyDamage(target, amount){ target.hp=Math.max(0,(target.hp ?? target.health)-amount); target.count=liveCount(target); return target.hp<=0; }
function specialFor(c){
  if(c.roles?.includes('tank')) return {key:'rempart', label:'Rempart', text:'Protège les unités adjacentes gauche/droite dans le même emplacement.'};
  if(c.roles?.includes('caster') && (c.name.toLowerCase().includes('mage') || c.power>55)) return {key:'fireball', label:'Boule de feu', text:'Tous les 3 jours: 3 dégâts en cercle sur un emplacement et ses voisins.'};
  if(c.roles?.includes('caster')) return {key:'spark', label:'Étincelle', text:'Début de tour: 1 dégât à une unité adverse aléatoire.'};
  if(c.roles?.includes('ranged')) return {key:'sentry', label:'Sentinelle', text:'Peut attaquer depuis l’arrière et soutient les lignes voisines.'};
  if(c.cost<=2) return {key:'mason', label:'Maçon', text:'Début de tour: répare +1 HP au mur allié.'};
  return {key:'none', label:'Instinct', text:'Aucun passif complexe.'};
}
function firstFreePos(slot, side='ally'){ const used=new Set(slotCards(slot,side).map(c=>c.pos??0)); for(let i=0;i<5;i++) if(!used.has(i)) return i; return -1; }
function isPosFree(slot, pos, side='ally'){ return pos>=0 && pos<5 && !slotCards(slot,side).some(c=>(c.pos??0)===pos); }
function chosenPosFor(slot){ return isPosFree(slot,state.pendingPos) ? state.pendingPos : firstFreePos(slot); }
function adjacentAllies(c){ return state.board.filter(x=>x.slot===c.slot && Math.abs((x.pos??0)-(c.pos??0))===1); }
function protectedByRempart(target){ return state.board.find(x=>x.uid!==target.uid && x.slot===target.slot && Math.abs((x.pos??0)-(target.pos??0))===1 && specialFor(x).key==='rempart'); }
function protectsByRempart(c){ return specialFor(c).key==='rempart' && adjacentAllies(c).length>0; }
function damageStack(target, amount, source=''){ const shield=protectedByRempart(target); if(shield){ const reduced=Math.max(1, amount-1); state.lastGuardUid=shield.uid; state.lastGuardTargetUid=target.uid; markHit(target.uid); addLog(`${shield.name} protège ${target.name}: Rempart absorbe ${amount-reduced} dégât, dégâts réduits à ${reduced}.`); amount=reduced; } return applyDamage(target, amount); }
function randomEnemyUnit(){ return rnd(state.enemyBoard); }
function randomAllyUnit(){ return rnd(state.board); }
function burnEnemyArea(pos, amount=3){ const victims=state.enemyBoard.filter(e=>Math.abs((e.pos??0)-pos)<=1).slice(0,5); if(!victims.length){ state.enemyStructures.wall=Math.max(0,state.enemyStructures.wall-amount); markHit('enemy-wall'); addLog(`Boule de feu frappe le mur adverse (${amount}).`); return; } victims.forEach(v=>{ const dead=applyDamage(v,amount); markHit(v.uid); addLog(`Boule de feu touche ${v.name} (${amount}).`); if(dead) state.enemyBoard=state.enemyBoard.filter(x=>x.uid!==v.uid); }); }
function applyStartOfTurnEffects(side='ally'){
  const list=side==='ally'?[...state.board]:[...state.enemyBoard];
  list.forEach(c=>{
    const sp=specialFor(c);
    if(sp.key==='mason' && side==='ally' && state.structures.wall>0 && state.structures.wall<20){ state.structures.wall=Math.min(20,state.structures.wall+1); markHit('ally-wall'); addLog(`${c.name} répare le mur (+1).`); }
    if(sp.key==='spark'){
      const t=side==='ally'?randomEnemyUnit():randomAllyUnit();
      if(t){ const dead=side==='ally'?applyDamage(t,1):damageStack(t,1); markHit(t.uid); addLog(`${c.name} déclenche Étincelle sur ${t.name} (1).`); if(dead){ if(side==='ally') state.enemyBoard=state.enemyBoard.filter(x=>x.uid!==t.uid); else state.board=state.board.filter(x=>x.uid!==t.uid); } }
    }
    if(sp.key==='fireball' && state.day%3===0){ if(side==='ally') burnEnemyArea(c.pos??2,3); else { const victims=state.board.filter(e=>Math.abs((e.pos??0)-(c.pos??2))<=1); victims.forEach(v=>{ const dead=damageStack(v,3); markHit(v.uid); addLog(`${c.name} lance une boule de feu sur ${v.name} (3).`); if(dead) state.board=state.board.filter(x=>x.uid!==v.uid); }); } }
  });
}
function quoteFor(c){ return QUOTES[(c.id + c.name.length + c.power) % QUOTES.length]; }
function loreFor(c){
  const nature = c.natures?.length ? c.natures.join(', ') : 'mystérieuse';
  const roles = c.roles?.length ? c.roles.join(', ') : 'inconnus';
  return `${c.name} est une créature ${nature} issue de l’arcane ${c.origin}. On la rencontre autour de ${c.capital}, où les mages l’emploient comme ${roles}. Sa taille (${c.size} m), sa puissance brute (${c.power}/100) et son tier ${tierFor(c)} déterminent son coût, ses HP et sa valeur [${stackCountFor(c)}]; quand elle est mise en jeu, elle invoque ${deployedUnitsFor(c)} unité(s).`;
}
function weightedCreature(){
  const roll=Math.random();
  let pool=CREATURES.filter(c=> roll>.97 ? c.rarity==='mythique' : roll>.84 ? c.rarity==='rare' : roll>.55 ? c.rarity==='inhabituelle' : c.rarity==='commune');
  if(!pool.length) pool=CREATURES;
  return rnd(pool);
}
function saveGame(){
  try { localStorage.setItem('fantasiafauna-save', JSON.stringify({gold:state.gold,day:state.day,collectionIds:state.collection.map(c=>c.id),deckIds:state.deckIds,location:state.location,playerHp:state.playerHp})); } catch {}
}
function loadGame(){
  try {
    const raw=localStorage.getItem('fantasiafauna-save'); if(!raw) return false;
    const data=JSON.parse(raw); state.gold=data.gold??80; state.day=data.day??1; state.location=data.location||'Camp du Mage'; state.playerHp=Math.max(90, data.playerHp??120);
    state.collection=(data.collectionIds||[]).map(id=>CREATURES.find(c=>c.id===id)).filter(Boolean);
    state.structures={tower:20,village:20,wall:20}; state.enemyStructures={tower:20,village:20,wall:20}; state.mana=6; state.maxMana=6;
    state.deckIds=(data.deckIds||[]).filter(id=>state.collection.some(c=>c.id===id));
    state.boosterOpened=state.collection.length>0; return state.boosterOpened;
  } catch { return false; }
}
function resetGame(){ localStorage.removeItem('fantasiafauna-save'); Object.assign(state,{gold:80,mana:6,maxMana:6,day:1,collection:[],deckIds:[],deck:[],hand:[],board:[],enemyBoard:[],graveyard:[],location:'Camp du Mage',mode:'world',boosterOpened:false,lastBooster:[],playerHp:120,selectedAttackerUid:null,pendingSlot:'front',pendingPos:0,lastHit:'',lastGuardUid:'',lastGuardTargetUid:'',structures:{tower:20,village:20,wall:20},enemyStructures:{tower:20,village:20,wall:20}}); startGame(true); }
function addLog(text){ state.log.unshift(text); state.log=state.log.slice(0,12); }
function startGame(forceNew=false){
  if(!forceNew && loadGame()){ addLog('Sauvegarde retrouvée: ta collection est chargée.'); render(); return; }
  openInitialBooster(); render();
}
function openInitialBooster(){
  state.lastBooster = Array.from({length:15}, weightedCreature);
  state.collection = [...state.lastBooster];
  state.deckIds = state.collection.slice(0,12).map(c=>c.id);
  state.deck = buildBattleDeck().map(clone);
  state.hand = state.deck.splice(0,4);
  state.boosterOpened=true;
  addLog('Booster initial ouvert: 15 cartes de créatures rejoignent ta collection.'); saveGame();
}
function draw(n=1){ for(let i=0;i<n;i++){ if(!state.deck.length) state.deck=shuffle(state.graveyard.splice(0)).map(c=>({...c, exhausted:false})); const c=state.deck.shift(); if(c) state.hand.push(c); } }
function deckLimit(){ return Math.min(18, state.collection.length); }
function buildBattleDeck(){
  const selected=[]; const used=new Set();
  state.deckIds.forEach(id=>{ const idx=state.collection.findIndex((c,i)=>c.id===id&&!used.has(i)); if(idx>=0){ selected.push(state.collection[idx]); used.add(idx); } });
  const fillers=state.collection.filter((_,i)=>!used.has(i));
  return shuffle([...selected, ...shuffle(fillers).slice(0, Math.max(0, deckLimit()-selected.length))]).slice(0, Math.max(1, deckLimit()));
}
function toggleDeckCard(id){
  const idNum=Number(id); const count=state.deckIds.filter(x=>x===idNum).length; const owned=state.collection.filter(c=>c.id===idNum).length;
  if(count>0){ const i=state.deckIds.indexOf(idNum); state.deckIds.splice(i,1); addLog('Carte retirée du grimoire de combat.'); }
  else if(state.deckIds.length>=deckLimit()){ addLog(`Grimoire plein: ${deckLimit()} cartes maximum pour le prochain duel.`); }
  else if(owned>0){ state.deckIds.push(idNum); addLog('Carte ajoutée au grimoire de combat.'); }
  saveGame(); render();
}
function resetFortifications(){ state.structures={tower:20,village:20,wall:20}; state.enemyStructures={tower:20,village:20,wall:20}; state.lastHit=''; state.lastGuardUid=''; state.lastGuardTargetUid=''; }
function newEncounter(kind='duel'){
  state.mode='battle'; state.enemyHp=999; state.playerHp=120; state.maxMana=6; state.mana=6; state.board=[]; state.enemyBoard=[]; state.hand=[]; state.deck=buildBattleDeck().map(clone); state.graveyard=[]; state.selectedAttackerUid=null; state.pendingSlot='front'; state.pendingPos=0; resetFortifications(); draw(5);
  addLog(kind==='boss'?'Un champion attaque ta tour.':'Un assaut commence: protège ta tour derrière le village et le mur.');
  addLog('Village actif: +6 points d’invocation par tour. Tour, village et mur ont chacun 20 HP.'); saveGame(); render();
}
function endTurn(){ state.selectedAttackerUid=null; applyStartOfTurnEffects('ally'); state.board.forEach(c=>c.exhausted=false); enemyTurn(); if(state.mode==='defeat') { saveGame(); render(); return; } state.day++; state.maxMana=6; state.mana=6; draw(1); addLog('Le village produit 6 points d’invocation.'); saveGame(); render(); }
function slotLabel(slot){ return slot==='wall'?'sur le mur':slot==='back'?'entre village et mur':'devant le mur'; }
function slotCards(slot, side='ally'){ const list=side==='enemy'?state.enemyBoard:state.board; return list.filter(c=>c.slot===slot).sort((a,b)=>(a.pos??0)-(b.pos??0)); }
function canPlaceInSlot(c, slot){ if(slot==='back') return c.cost<=3 || c.roles.includes('ranged') || c.roles.includes('caster'); return true; }
function setPlacement(slot=state.pendingSlot, pos=state.pendingPos){ state.pendingSlot=slot; const wanted=Math.max(0, Math.min(4, Number(pos)||0)); state.pendingPos=isPosFree(slot,wanted)?wanted:Math.max(0, firstFreePos(slot)); addLog(`Placement choisi: ${slotLabel(slot)}, colonne ${state.pendingPos+1}. Clique ensuite une carte de ta main.`); render(); }
function setPendingSlot(slot){ setPlacement(slot, state.pendingPos); }
function setPendingPos(pos){ setPlacement(state.pendingSlot, pos); }
function enemyTurn(){
  const enemyCard=clone(weightedCreature()); enemyCard.slot=enemyCard.roles.includes('ranged')||enemyCard.roles.includes('caster')?'back':'front'; enemyCard.pos=firstFreePos(enemyCard.slot,'enemy'); if(enemyCard.pos<0) enemyCard.pos=Math.floor(Math.random()*5);
  if(state.enemyBoard.length<7) { state.enemyBoard.push(enemyCard); addLog(`Ennemi invoque ${enemyCard.name} ${slotLabel(enemyCard.slot)}.`); }
  applyStartOfTurnEffects('enemy');
  [...state.enemyBoard].forEach(e=> enemyAttack(e));
  if(state.structures.tower<=0){ state.mode='defeat'; addLog('Ta tour tombe à 0 HP: défaite immédiate.'); }
}
function markHit(key){ state.lastHit=key; if(key!==state.lastGuardTargetUid){ state.lastGuardUid=''; state.lastGuardTargetUid=''; } }
function damageStructure(which, amount){ state.structures[which]=Math.max(0,state.structures[which]-amount); markHit('ally-'+which); }
function enemyAttack(e){
  const dmg=strikePower(e); let target=null;
  if(e.roles.includes('volant')){
    if(state.structures.wall>0) { damageStructure('wall',dmg); addLog(`${e.name} [${e.count}] vole au-dessus du front et frappe le mur (${dmg}).`); return; }
    damageStructure('tower',dmg); addLog(`${e.name} [${e.count}] vole directement sur la tour (${dmg}).`); return;
  }
  target=slotCards('front')[0];
  if(target){ const dead=damageStack(target,dmg); markHit(target.uid); addLog(`${e.name} [${e.count}] frappe la ligne devant le mur: ${target.name} (${dmg}).`); if(dead){ state.graveyard.push(target); state.board=state.board.filter(c=>c.uid!==target.uid); } return; }
  if(state.structures.wall>0){ damageStructure('wall',dmg); addLog(`${e.name} [${e.count}] attaque le mur (${dmg}).`); return; }
  target=slotCards('wall')[0];
  if(target){ const dead=damageStack(target,dmg); markHit(target.uid); addLog(`${e.name} [${e.count}] grimpe sur le mur et frappe ${target.name} (${dmg}).`); if(dead){ state.graveyard.push(target); state.board=state.board.filter(c=>c.uid!==target.uid); } return; }
  target=slotCards('back')[0];
  if(target){ const dead=damageStack(target,dmg); markHit(target.uid); addLog(`${e.name} [${e.count}] perce jusqu’au village et frappe ${target.name} (${dmg}).`); if(dead){ state.graveyard.push(target); state.board=state.board.filter(c=>c.uid!==target.uid); } return; }
  damageStructure('tower',dmg); addLog(`${e.name} [${e.count}] frappe la tour (${dmg}).`);
}
function playCard(uid, slot=state.pendingSlot){ const c=state.hand.find(x=>x.uid===uid); const pos=chosenPosFor(slot); if(!c || c.cost>state.mana || state.board.length>=15) return; if(pos<0){ addLog('Cette zone est pleine: les 5 colonnes sont occupées.'); render(); return; } if(!canPlaceInSlot(c,slot)){ addLog(slot==='wall'?'Le mur n’a que 5 colonnes de défense.':'Cette zone arrière accepte surtout les faibles, ranged ou casters.'); render(); return; } state.hand=state.hand.filter(x=>x.uid!==uid); state.mana-=c.cost; c.exhausted=true; c.slot=slot; c.pos=pos; state.pendingPos=pos; state.board.push(c); state.selectedAttackerUid=null; const sp=specialFor(c); addLog(`${c.name} rejoint ${slotLabel(slot)}, colonne ${pos+1}. Effet: ${sp.label}.`); if(c.roles.includes('caster')) damageRandomEnemy(2); if(c.roles.includes('normal')) c.attack+=1; saveGame(); render(); }
function damageRandomEnemy(n){ const target=state.enemyBoard[0]; if(target){ const dead=applyDamage(target,n); markHit(target.uid); addLog(`Sort: ${target.name} subit ${n}.`); if(dead) state.enemyBoard.shift(); } else { state.enemyStructures.wall=Math.max(0,state.enemyStructures.wall-n); markHit('enemy-wall'); addLog(`Sort direct: mur adverse -${n} HP.`); } }
function selectAttacker(uid){ const c=state.board.find(x=>x.uid===uid); if(!c) return; if(c.exhausted){ addLog(`${c.name} a déjà agi ce tour.`); state.selectedAttackerUid=null; render(); return; } if(c.slot==='back' && !(c.roles.includes('ranged')||c.roles.includes('caster')||c.roles.includes('volant'))){ addLog(`${c.name} est entre village et mur: pas d’attaque de mêlée depuis cette position.`); state.selectedAttackerUid=null; render(); return; } state.selectedAttackerUid=state.selectedAttackerUid===uid?null:uid; addLog(state.selectedAttackerUid?`${c.name} est prêt: choisis une cible ennemie ou une structure.`:'Attaque annulée.'); render(); }
function canHitTarget(target){ const front=state.enemyBoard.find(x=>x.slot==='front'); const c=state.board.find(x=>x.uid===state.selectedAttackerUid); if(c?.roles.includes('volant')) return true; return !front || front.uid===target.uid || c?.roles.includes('ranged'); }
function resolveAttack(c,target){ if(target){ const dealt=strikePower(c); const dead=applyDamage(target,dealt); if(!c.roles.includes('ranged')&&!c.roles.includes('volant')) damageStack(c,strikePower(target)); markHit(target.uid); addLog(`${c.name} [${c.count}] attaque ${target.name} (${dealt}).`); if(dead) state.enemyBoard=state.enemyBoard.filter(x=>x.uid!==target.uid); if(c.hp<=0){ state.graveyard.push(c); state.board=state.board.filter(x=>x.uid!==c.uid); }} else { attackEnemyStructure(c); return; } c.exhausted=true; state.selectedAttackerUid=null; saveGame(); render(); }
function attackTarget(uid){ const c=state.board.find(x=>x.uid===state.selectedAttackerUid); const target=state.enemyBoard.find(x=>x.uid===uid); if(!c||!target) return; if(!canHitTarget(target)){ const front=state.enemyBoard.find(x=>x.slot==='front'); addLog(`Ligne normale: ${front.name} devant le mur doit être ciblé avant les autres.`); render(); return; } resolveAttack(c,target); }
function structureLabel(key){ return key==='tower'?'la tour adverse':key==='village'?'le village adverse':'le mur adverse'; }
function attackEnemyStructure(c, requested='auto'){
  const dmg=strikePower(c); const fly=c.roles.includes('volant');
  let target=requested;
  if(target==='auto') target = fly && state.enemyStructures.tower>0 ? 'tower' : state.enemyStructures.wall>0 ? 'wall' : 'tower';
  if(!['tower','village','wall'].includes(target)) target='wall';
  if(state.enemyStructures[target]<=0){ addLog(`${structureLabel(target)} est déjà détruit.`); state.selectedAttackerUid=null; render(); return; }
  state.enemyStructures[target]=Math.max(0,state.enemyStructures[target]-dmg); markHit('enemy-'+target); addLog(`${c.name} [${c.count}] frappe ${structureLabel(target)} (${dmg}).`); c.exhausted=true; state.selectedAttackerUid=null; if(state.enemyStructures.tower<=0){ state.gold+=45; const prize=weightedCreature(); state.collection.push(prize); addLog(`Victoire: la tour adverse tombe. +45 or et carte gagnée: ${prize.name}.`); state.mode='world'; } saveGame(); render(); }
function attackEnemyStructureTarget(target='auto'){ const c=state.board.find(x=>x.uid===state.selectedAttackerUid); if(!c){ addLog('Sélectionne d’abord une créature alliée prête, puis une structure adverse.'); render(); return; } attackEnemyStructure(c,target); }
function attackEnemyMage(){ attackEnemyStructureTarget('auto'); }
function attackWith(uid){ selectAttacker(uid); }
function buyBooster(){ if(state.gold<60){ addLog('Pas assez d’or pour acheter un booster.'); render(); return; } state.gold-=60; const cards=Array.from({length:5}, weightedCreature); state.collection.push(...cards); cards.forEach(c=>{ if(state.deckIds.length<deckLimit()) state.deckIds.push(c.id); }); state.lastBooster=cards; addLog('Booster acheté: '+cards.map(c=>c.name).join(', ')); saveGame(); render(); }
function tradeCard(){ if(state.gold<25){ addLog('Pas assez d’or pour échanger au marché.'); render(); return; } state.gold-=25; const pool = state.activeCapital==='Toutes' ? CREATURES : CREATURES.filter(c=>c.capital===state.activeCapital); const card=rnd(pool.length?pool:CREATURES); state.collection.push(card); if(state.deckIds.length<deckLimit()) state.deckIds.push(card.id); state.lastBooster=[card]; addLog(`Marché: tu obtiens ${card.name}.`); saveGame(); render(); }
function travel(loc){ state.location=loc.name; state.gold+=loc.gold||0; if(loc.capital) state.activeCapital=loc.capital; if(loc.type==='town') addLog(`Arrivée à ${loc.name}: boutique orientée ${loc.capital||'toutes factions'}.`); if(loc.type==='duel') newEncounter(); else if(loc.type==='boss') newEncounter('boss'); else { saveGame(); render(); } }
const LOCATIONS=[
  {name:'Citadelle d’Aurore',type:'town',capital:'Citadelle',x:14,y:20},{name:'Sylve Ancienne',type:'town',capital:'Sylve',x:36,y:18},{name:'Forteresse des Runes',type:'town',capital:'Forteresse',x:72,y:23},{name:'Hameau des Lanternes',type:'town',capital:'Hameau',x:26,y:66},{name:'Nécropole Voilée',type:'duel',capital:'Nécropole',x:61,y:69},{name:'Abîme des Miroirs',type:'boss',capital:'Abîme',x:83,y:62},{name:'Caravane du Désert',type:'town',capital:'Désert',x:53,y:43},{name:'Tour des Pactes',type:'duel',capital:'Tour',x:46,y:29}
];
function cardView(c, zone='preview'){
  const color=CAPITAL_COLORS[c.capital]||'#c9aa69'; const img=c.image?`<img src="${encodeURI(c.image)}" alt="${c.name}" decoding="async">`:'';
  const action = zone==='hand'?`onclick="playCard('${c.uid}')"`:zone==='ally'?`onclick="event.stopPropagation();selectAttacker('${c.uid}')"`:zone==='enemy'?`onclick="event.stopPropagation();attackTarget('${c.uid}')"`:'';
  const selected = c.uid && state.selectedAttackerUid===c.uid ? ' selected' : '';
  return `<article class="ff-card ${c.rarity} ${zone}${selected}" style="--faction:${color}" ${action}>
    <header class="card-title"><span>${c.name}</span><b>${c.cost}</b></header>
    <div class="card-art">${img}<i>${c.capital}</i></div>
    <div class="type-line">Créature · ${c.origin} · ${c.natures.join(' / ')}</div>
    <p class="ability"><strong>${c.spell.split(':')[0]}.</strong> ${c.spell.includes(':')?c.spell.split(':').slice(1).join(':').trim():c.spell}</p>
    <p class="lore">${loreFor(c)}</p>
    <blockquote>${quoteFor(c)}</blockquote>
    <footer class="card-stats"><span><small>ATQ</small>${c.attack}</span><span><small>HP</small>${displayHp(c)}</span><span><small>[ ]</small>${c.count || stackCountFor(c)}</span></footer>
  </article>`;
}
function compactCard(c, zone){
  const color=CAPITAL_COLORS[c.capital]||'#c9aa69'; const img=c.image?`<img src="${encodeURI(c.image)}" alt="${c.name}" decoding="async">`:'';
  const action = zone==='hand'?`onclick="playCard('${c.uid}')"`:zone==='ally'?`onclick="event.stopPropagation();selectAttacker('${c.uid}')"`:zone==='enemy'?`onclick="event.stopPropagation();attackTarget('${c.uid}')"`:'';
  const selected = c.uid && state.selectedAttackerUid===c.uid ? ' selected' : '';
  const guard = zone==='ally' && c.uid ? protectedByRempart(c) : null;
  const protector = zone==='ally' && c.uid && protectsByRempart(c);
  const guardClass = guard ? ' guarded' : protector ? ' protector' : '';
  const flashClass = c.uid===state.lastGuardUid ? ' guard-flash' : c.uid===state.lastGuardTargetUid ? ' guarded-hit' : '';
  const guardBadge = guard ? `<small class="guard-badge">Protégé par ${guard.name}</small>` : protector ? '<small class="guard-badge">Rempart actif ↔</small>' : '';
  const impactBadge = c.uid===state.lastGuardUid ? '<small class="guard-badge impact-badge">Rempart -1 dégât</small>' : c.uid===state.lastGuardTargetUid ? '<small class="guard-badge impact-badge">Dégât amorti</small>' : '';
  return `<button class="battle-card ${c.rarity} ${zone}${selected}${guardClass}${flashClass}" style="--faction:${color}" ${action}><span class="cost">${c.cost}</span><div class="art">${img}</div><strong>${c.name}</strong><small>${c.capital} · ${c.rarity}</small><p>${c.spell}</p><small class="special">${specialFor(c).label}: ${specialFor(c).text}</small>${guardBadge}${impactBadge}<footer><b>${c.attack}</b><span>${displayHp(c)}</span><em>[${stackCountFor(c)}]</em></footer>${c.uid?`<small class="unit-count">Unités: ${liveCount(c)}/${deployedUnitsFor(c)}</small>`:''}</button>`;
}
function filteredCreatures(){
  const q=state.search.trim().toLowerCase();
  return CREATURES.filter(c=>(state.activeCapital==='Toutes'||c.capital===state.activeCapital)&&(!q||[c.name,c.capital,c.origin,c.rarity,...c.roles,...c.natures].join(' ').toLowerCase().includes(q)))
    .sort((a,b)=>b.power-a.power || b.popularity-a.popularity);
}
function setFilter(cap){ state.activeCapital=cap; render(); }
function setSearch(v){ state.search=v; render(); }
function renderShowcase(){
  const caps=['Toutes',...Array.from(new Set(CREATURES.map(c=>c.capital))).slice(0,14)];
  const picks=filteredCreatures().slice(0,12);
  return `<section class="showcase panel"><div class="section-head"><div><p class="eyebrow">MVP cartes jouables</p><h2>Rectos de cartes inspirés de Magic</h2><p>Chaque créature devient une carte avec coût d’invocation, attaque, HP, valeur [ ], origine, histoire courte, citation et capacité intégrée.</p></div><div class="searchbox"><input value="${state.search}" oninput="setSearch(this.value)" placeholder="Chercher dragon, caster, Nécropole…"><button onclick="resetGame()">Nouvelle aventure</button></div></div><div class="filters">${caps.map(c=>`<button class="${state.activeCapital===c?'active':''}" onclick="setFilter('${c.replaceAll("'","\\'")}')">${c}</button>`).join('')}</div><div class="card-gallery">${picks.map(c=>cardView(c)).join('')}</div></section>`;
}
function renderBooster(){
  if(!state.lastBooster.length) return '';
  return `<section class="panel booster"><h2>Dernier booster / gain</h2><div class="booster-row">${state.lastBooster.slice(-5).map(c=>cardView(c)).join('')}</div></section>`;
}
function renderWorld(){ return `${renderShowcase()}${renderBooster()}<section class="panel map-panel"><h2>Carte du monde</h2><div class="world-map">${LOCATIONS.map(l=>`<button class="place ${l.type}" style="left:${l.x}%;top:${l.y}%" onclick='travel(${JSON.stringify(l)})'><span>${l.name}</span></button>`).join('')}</div></section>
<section class="panel actions"><h2>${state.location}</h2><p>Explore, achète des cartes, provoque des duels de stacks et construis un grimoire de créatures-sort. Le marché actuel vise: <b>${state.activeCapital}</b>.</p><button onclick="buyBooster()">Acheter booster — 60 or</button><button onclick="tradeCard()">Échanger au marché — 25 or</button><button onclick="newEncounter()">Duel rapide</button><h3>Grimoire de combat (${state.deckIds.length}/${deckLimit()})</h3><p class="deck-hint">Clique une carte de collection pour l’ajouter ou la retirer du deck du prochain duel; les places libres sont complétées automatiquement.</p><div class="deck-list">${state.deckIds.slice(0,18).map(id=>{const c=CREATURES.find(x=>x.id===id);return c?`<button onclick="toggleDeckCard(${id})">${c.name}<small>${c.cost} mana · ${c.rarity}</small></button>`:''}).join('')||'<em>Aucune carte verrouillée: deck auto.</em>'}</div><h3>Collection récente</h3><div class="collection-strip">${state.collection.slice(-12).map(c=>`<div class="collection-pick ${state.deckIds.includes(c.id)?'picked':''}" onclick="toggleDeckCard(${c.id})">${compactCard(clone(c),'preview')}</div>`).join('')}</div></section>`; }
function hpBar(label, val, side, key){ const pct=Math.max(0,Math.min(100,val*5)); return `<div class="structure ${side} ${state.lastHit===side+'-'+key?'hit':''}"><b>${label}</b><span>${val}/20 HP</span><i style="width:${pct}%"></i></div>`; }
function renderSlot(slot, side){ const list=side==='enemy'?state.enemyBoard:state.board; const cells=Array.from({length:5},(_,i)=>list.filter(c=>c.slot===slot && (c.pos??0)===i).map(c=>compactCard(c,side==='enemy'?'enemy':'ally')).join('')||'<em>vide</em>').map((html,i)=>`<div class="cell ${side==='ally'&&state.pendingSlot===slot&&state.pendingPos===i?'chosen':''}" ${side==='ally'?`onclick="setPlacement('${slot}',${i})"`:''}><b>${i+1}</b>${html}</div>`).join(''); return `<div class="lane ${slot} ${side}"><h4>${slotLabel(slot)} · 5 emplacements verticaux</h4><div class="lane-cards cells">${cells}</div></div>`; }
function renderBattle(){ return `<section class="battle siege-battle"><div class="battle-help"><b>Règle d’assaut:</b> l’ennemi détruit devant le mur → mur → créatures sur le mur → créatures entre village et mur → tour. Vol peut viser le mur/la tour. Le village donne 6 points par tour.</div><div class="siege-grid"><div class="side-field enemy-side"><h2>Ennemi</h2><div class="village-art enemy-village"><span>Village ennemi</span></div><div class="structures">${hpBar('Tour',state.enemyStructures.tower,'enemy','tower')}${hpBar('Village',state.enemyStructures.village,'enemy','village')}${hpBar('Mur',state.enemyStructures.wall,'enemy','wall')}</div>${renderSlot('back','enemy')}${renderSlot('wall','enemy')}${renderSlot('front','enemy')}<div class="structure-targets"><b>Cibler une structure</b><button onclick="attackEnemyStructureTarget('tower')">Tour</button><button onclick="attackEnemyStructureTarget('village')">Village</button><button onclick="attackEnemyStructureTarget('wall')">Mur</button><button class="mage-target" onclick="attackEnemyMage()">Auto</button></div></div><div class="center-controls"><span>Invocation ${state.mana}/6</span><button onclick="endTurn()">Fin du tour</button><div class="placement-guide"><b>Ordre tactique</b><ol><li>Clique une zone/colonne alliée.</li><li>Clique une carte de ta main.</li><li>Pour attaquer: carte alliée prête → cible ennemie/structure.</li></ol><strong>Placement actif: ${slotLabel(state.pendingSlot)}, colonne ${state.pendingPos+1}</strong></div><p>${state.selectedAttackerUid?'Cible une créature/structure ennemie.':'Choisis une zone puis joue une carte, ou clique une créature alliée prête.'}</p></div><div class="side-field ally-side"><h2>Ta défense</h2><div class="village-art ally-village"><span>Village +6/tour</span></div><div class="structures">${hpBar('Tour',state.structures.tower,'ally','tower')}${hpBar('Village',state.structures.village,'ally','village')}${hpBar('Mur',state.structures.wall,'ally','wall')}</div>${renderSlot('front','ally')}${renderSlot('wall','ally')}${renderSlot('back','ally')}<div class="slot-picker"><button class="${state.pendingSlot==='front'?'active':''}" onclick="setPendingSlot('front')">Jouer devant</button><button class="${state.pendingSlot==='wall'?'active':''}" onclick="setPendingSlot('wall')">Jouer sur mur (${slotCards('wall').length}/5)</button><button class="${state.pendingSlot==='back'?'active':''}" onclick="setPendingSlot('back')">Jouer arrière</button></div><h3>Main</h3><div class="hand">${state.hand.map(c=>compactCard(c,'hand')).join('')}</div></div></div></section>`; }
function renderDefeat(){ return `<section class="panel defeat"><h2>Tour détruite</h2><p>Ta tour est tombée à 0 HP. L’assaut est perdu.</p><button onclick="resetGame()">Nouvelle aventure</button><button onclick="newEncounter()">Rejouer un assaut</button></section>`; }
function render(){ byId('app').innerHTML=`<header class="topbar"><div><p class="eyebrow">Fantasia Fauna</p><h1>Arcanes du Bestiaire</h1><p class="subtitle">MVP: bestiaire transformé en stacks de créatures, cartes de collection et combats de mages.</p></div><div class="stats"><span>Jour ${state.day}</span><span>${state.gold} or</span><span>${state.collection.length} cartes</span><span>${state.playerHp} PV mage</span><span>${CREATURES.length} créatures</span></div></header><main>${state.mode==='defeat'?renderDefeat():state.mode==='battle'?renderBattle():renderWorld()}</main><aside class="log"><h2>Journal</h2>${state.log.map(x=>`<p>${x}</p>`).join('')}</aside>`; }
window.playCard=playCard; window.setPlacement=setPlacement; window.setPendingSlot=setPendingSlot; window.setPendingPos=setPendingPos; window.attackWith=attackWith; window.selectAttacker=selectAttacker; window.attackTarget=attackTarget; window.attackEnemyStructureTarget=attackEnemyStructureTarget; window.attackEnemyMage=attackEnemyMage; window.endTurn=endTurn; window.buyBooster=buyBooster; window.tradeCard=tradeCard; window.travel=travel; window.newEncounter=newEncounter; window.toggleDeckCard=toggleDeckCard; window.setFilter=setFilter; window.setSearch=setSearch; window.resetGame=resetGame;
startGame();
